package com.fullstack.exp232.service;
import com.fullstack.exp232.model.TokenResponse; import com.fullstack.exp232.security.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import java.sql.Timestamp; import java.time.LocalDateTime;
@Service public class TokenService {private final JdbcTemplate db;private final JwtService jwt;private final AesEncryptionService aes;public TokenService(JdbcTemplate db,JwtService jwt,AesEncryptionService aes){this.db=db;this.jwt=jwt;this.aes=aes;}public TokenResponse issue(String u){String a=jwt.access(u),r=jwt.refresh(u);db.update("DELETE FROM refresh_tokens WHERE username=?",u);db.update("INSERT INTO refresh_tokens(username,encrypted_token,expires_at) VALUES(?,?,?)",u,aes.encrypt(r),Timestamp.valueOf(LocalDateTime.now().plusDays(1)));return new TokenResponse(a,r);}public TokenResponse refresh(String r){String u=jwt.username(r);var x=db.query("SELECT encrypted_token,expires_at FROM refresh_tokens WHERE username=?",(rs,n)->new Object[]{rs.getString(1),rs.getTimestamp(2)},u);if(x.isEmpty()||!aes.decrypt((String)x.get(0)[0]).equals(r)||((Timestamp)x.get(0)[1]).before(new Timestamp(System.currentTimeMillis())))throw new IllegalArgumentException();return issue(u);}public String store(String p,String c){String e=aes.encrypt(c);db.update("INSERT INTO oauth_credentials(provider,encrypted_value) VALUES(?,?)",p,e);return e;}public String read(String p){return db.queryForObject("SELECT encrypted_value FROM oauth_credentials WHERE provider=? ORDER BY id DESC LIMIT 1",String.class,p);}}
